   async exportAllData(): Promise<void> {
      const allData = await this.fetchAllPagesFiltered();    
      const worksheet: XLSX.WorkSheet = XLSX.utils.json_to_sheet(allData);
      const workbook: XLSX.WorkBook = { Sheets: { data: worksheet }, SheetNames: ['data'] };
      const excelBuffer: any = XLSX.write(workbook, { bookType: 'xlsx', type: 'array' });
    
      const blobData: Blob = new Blob([excelBuffer], { type: 'application/octet-stream' });
      FileSaver.saveAs(blobData, 'donation.xlsx');
    }

